import Link from "next/link";

import { buttonVariants } from "@/components/ui/button";

// Quem já tem sessão é mandado para /dashboard pelo proxy.
export default function HomePage() {
  return (
    <section className="mx-auto flex max-w-3xl flex-1 flex-col items-center justify-center gap-6 px-4 py-24 text-center">
      <h1 className="text-4xl font-bold tracking-tight sm:text-6xl">
        Filme <span className="text-primary">Certo</span>
      </h1>
      <p className="text-muted-foreground max-w-xl text-lg">
        Conte do que você gosta e receba recomendações de filmes feitas para o seu gosto, com onde
        assistir no Brasil.
      </p>
      <div className="flex flex-wrap justify-center gap-3">
        <Link href="/cadastro" className={buttonVariants({ size: "lg", className: "h-10 px-5" })}>
          Criar conta
        </Link>
        <Link
          href="/login"
          className={buttonVariants({ variant: "outline", size: "lg", className: "h-10 px-5" })}
        >
          Entrar
        </Link>
      </div>
    </section>
  );
}
import { Search } from "lucide-react";
import Link from "next/link";

import { Button, buttonVariants } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { sair } from "@/features/auth/actions";
import { obterUsuarioAtual } from "@/features/auth/sessao";

export async function Header() {
  const usuario = await obterUsuarioAtual();

  return (
    <header className="border-border/60 bg-background/80 sticky top-0 z-40 border-b backdrop-blur">
      <div className="mx-auto flex h-16 max-w-6xl items-center justify-between gap-4 px-4">
        <Link href={usuario ? "/dashboard" : "/"} className="text-xl font-bold tracking-tight">
          Filme <span className="text-primary">Certo</span>
        </Link>
        <nav
          aria-label="Navegação principal"
          className="text-muted-foreground flex items-center gap-4 text-sm"
        >
          <Link href="/sobre" className="hover:text-foreground transition-colors">
            Sobre
          </Link>
          {usuario ? (
            <>
              <form action="/busca" method="get" role="search" className="hidden sm:block">
                <Input
                  name="q"
                  type="search"
                  aria-label="Buscar filmes"
                  placeholder="Buscar filmes…"
                  className="h-8 w-44 lg:w-56"
                />
              </form>
              <Link
                href="/busca"
                aria-label="Buscar filmes"
                className="hover:text-foreground transition-colors sm:hidden"
              >
                <Search className="size-5" aria-hidden="true" />
              </Link>
              <Link href="/listas" className="hover:text-foreground transition-colors">
                Minhas listas
              </Link>
              <Link
                href="/perfil"
                className="text-foreground hover:text-primary hidden max-w-40 truncate transition-colors sm:inline"
              >
                {usuario.nome}
              </Link>
              <form action={sair}>
                <Button type="submit" variant="outline" size="sm">
                  Sair
                </Button>
              </form>
            </>
          ) : (
            <>
              <Link href="/login" className="hover:text-foreground transition-colors">
                Entrar
              </Link>
              <Link href="/cadastro" className={buttonVariants({ size: "sm" })}>
                Criar conta
              </Link>
            </>
          )}
        </nav>
      </div>
    </header>
  );
}
export default function AuthLayout({ children }: LayoutProps<"/">) {
  return (
    <section className="flex flex-1 items-center justify-center px-4 py-16">
      <div className="border-border/60 bg-card w-full max-w-sm rounded-xl border p-6 shadow-sm sm:p-8">
        {children}
      </div>
    </section>
  );
}
import type { Metadata } from "next";

import { LoginForm } from "@/features/auth/components/login-form";
import { sanitizarNext } from "@/features/auth/redirecionamento";

export const metadata: Metadata = { title: "Entrar" };

export default async function LoginPage({ searchParams }: PageProps<"/login">) {
  const { next } = await searchParams;
  const destino = typeof next === "string" ? sanitizarNext(next) : undefined;

  return (
    <>
      <h1 className="mb-1 text-2xl font-bold tracking-tight">Entrar</h1>
      <p className="text-muted-foreground mb-6 text-sm">Bom te ver de novo.</p>
      <LoginForm next={destino} />
    </>
  );
}
import { redirect } from "next/navigation";

import { exigirUsuario } from "@/features/auth/sessao";
import { obterPreferencias } from "@/features/preferencias/consultas";

/**
 * Área logada. O proxy já redireciona quem não tem sessão; esta é a checagem
 * definitiva, e também manda para o onboarding quem ainda não o concluiu.
 */
export default async function AppLayout({ children }: LayoutProps<"/">) {
  await exigirUsuario();
  if (!(await obterPreferencias())) redirect("/onboarding");
  return <>{children}</>;
}
