        <Link href={proximaRodada} className={buttonVariants({ variant: "outline" })}>
          Tentar outras recomendações
        </Link>
      </div>
    );
  }

  return secoes.map((secao) => (
    <SecaoRecomendacoes key={secao.id} secao={secao} urlAtual={urlAtual} />
  ));
}

