      {/* A chave por rodada mostra o esqueleto de novo a cada "Gerar outras recomendações". */}
      <Suspense key={rodada} fallback={<EsqueletoSecoes />}>
        <SecoesRecomendadas
          entrada={{
            preferencias,
            usuarioId: usuario.id,
            data: new Date(),
            rodada,
            reacoes,
            excluir,
          }}
          urlAtual={urlAtual}
          proximaRodada={proximaRodada}
          meio={
